--- a/training/level-1/L1-030-idempotency-key/idempotencyKey.mjs
+++ b/training/level-1/L1-030-idempotency-key/idempotencyKey.mjs
@@ -0,0 +1,50 @@
+import { createHash } from 'node:crypto';
+
+function canonicalize(value) {
+  if (typeof value === 'string') {
+    return JSON.stringify(value);
+  } else if (typeof value === 'number' || typeof value === 'boolean' || value === null) {
+    return JSON.stringify(value);
+  } else if (Array.isArray(value)) {
+    return '[' + value.map(canonicalize).join(',') + ']';
+  } else if (value instanceof Object) {
+    const keys = Object.keys(value).sort();
+    if (keys.length === 0) {
+      return '{}';
+    }
+    let result = '{';
+    for (let i = 0; i < keys.length; i++) {
+      const key = keys[i];
+      const val = value[key];
+      result += JSON.stringify(key) + ':' + canonicalize(val);
+      if (i < keys.length - 1) {
+        result += ',';
+      }
+    }
+    result += '}';
+    return result;
+  } else {
+    throw new TypeError('Invalid value type');
+  }
+}
+
+export function idempotencyKey(value, options = {}) {
+  const namespace = options.namespace || 'othrys';
+  
+  if (typeof namespace !== 'string' || namespace.trim() === '') {
+    throw new RangeError('namespace must be a non-empty string');
+  }
+  
+  const trimmedNamespace = namespace.trim();
+  
+  try {
+    const canonicalized = canonicalize(value);
+    const hash = createHash('sha256').update(canonicalized, 'utf8').digest('hex');
+    return `${trimmedNamespace}:${hash}`;
+  } catch (error) {
+    if (error instanceof TypeError || error instanceof RangeError) {
+      throw error;
+    }
+    throw new TypeError('Invalid value for idempotencyKey');
+  }
+}

